import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class HttpStatusClassifier {
    public static Map<Integer, List<String>> groupByStatusCode(List<String[]> logLines) {
        Map<Integer, List<String>> classified = new HashMap<>();

        for (String[] log : logLines) {
            String path = log[0];
            int status = Integer.parseInt(log[1]);

            // computeIfAbsent creates list on first encounter, appends path in O(1)
            classified.computeIfAbsent(status, k -> new ArrayList<>()).add(path);
        }
        return classified;
    }

    public static void main(String[] args) {
        List<String[]> logs = List.of(
            new String[]{"/api/v1/users", "200"},
            new String[]{"/api/v1/login", "401"},
            new String[]{"/api/v1/orders", "200"},
            new String[]{"/api/v1/admin", "403"},
            new String[]{"/api/v1/pay", "500"}
        );

        Map<Integer, List<String>> report = groupByStatusCode(logs);
        report.forEach((status, endpoints) -> 
            System.out.printf("Status %d: %s%n", status, endpoints));
    }
}

