import java.util.Map;
import java.util.HashMap;

public class TokenFrequency {
    public static Map<String, Integer> countFrequencies(String[] tokens) {
        Map<String, Integer> freq = new HashMap<>();
        if (tokens != null) {
            for (String t : tokens) {
                if (t != null) {
                    freq.merge(t, 1, Integer::sum);
                }
            }
        }
        return freq;
    }
}

