import java.util.Map;

public class ScorePurge {
    public static void purgeBelowThreshold(Map<String, Integer> scores, int minPassing) {
        if (scores != null) {
            scores.entrySet().removeIf(entry -> entry.getValue() == null || entry.getValue() < minPassing);
        }
    }
}

