import java.util.List;
import java.util.Map;
import java.util.HashMap;

public class WordLengthMapper {
    public static Map<String, Integer> mapLengths(List<String> words) {
        Map<String, Integer> map = new HashMap<>();
        if (words != null) {
            for (String w : words) {
                if (w != null) {
                    map.put(w, w.length());
                }
            }
        }
        return map;
    }
}
